import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";import{U as i}from"./chunks/assets.DeBnt35C.js";var a=JSON.parse(`{"title":"基础","description":"","frontmatter":{},"headers":[],"relativePath":"middleware/kafka/basic/index.md","filePath":"middleware/kafka/basic/index.md"}`),o={name:`middleware/kafka/basic/index.md`};function s(r,a,o,s,c,l){return n(),e(`div`,null,[...a[0]||=[t(`<h1 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to “基础”">​</a></h1><ul><li><p>是一款高吞吐、可持久化、分布式的流处理平台，核心用于实时数据的收集、存储与分发。</p></li><li><p>详解：<a href="https://www.bilibili.com/video/BV1TT421y79S/?spm_id_from=333.337.search-card.all.click&amp;vd_source=ad7a7015d055e3611329c5a5f9a00794" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1TT421y79S/?spm_id_from=333.337.search-card.all.click&amp;vd_source=ad7a7015d055e3611329c5a5f9a00794</a></p></li></ul><h2 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h2><ul><li><strong>超高吞吐量</strong>：通过 “顺序读写磁盘” 和 “批量传输” 机制，单 Broker 可轻松支撑每秒数十万条消息的处理。</li><li><strong>高可靠性</strong>：数据默认持久化到磁盘，支持多副本（Replica）机制，某台 Broker 故障时，副本可自动接管服务。</li><li><strong>分布式弹性</strong>：Broker、Partition 均支持分布式部署，可通过增加节点轻松扩展集群容量和处理能力。</li><li><strong>低延迟</strong>：通过零拷贝（Zero-Copy）技术减少数据在内存与磁盘间的拷贝次数，端到端延迟可低至毫秒级。</li></ul><h2 id="架构图" tabindex="-1">架构图 <a class="header-anchor" href="#架构图" aria-label="Permalink to “架构图”">​</a></h2><p><img src="`+i+`" alt="" width="1303" height="696"></p><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to “应用场景”">​</a></h2><ul><li><strong>日志收集</strong>：收集多台服务器的应用日志，统一存储并分发给 ELK（Elasticsearch, Logstash, Kibana）等系统进行分析。</li><li><strong>实时数据管道</strong>：作为数据中台的核心，连接上游数据源（如数据库、业务系统）与下游数据应用（如实时报表、机器学习模型）。</li><li><strong>流处理</strong>：与 Flink、Spark Streaming 等流处理框架结合，实现实时数据计算，如实时风控、实时推荐。</li><li><strong>消息系统</strong>：替代传统的消息队列（如 RabbitMQ），用于高吞吐的业务解耦，如订单状态通知、库存变更同步。</li></ul>`,8)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};